<script setup>
import {Head,Link,router,usePage} from '@inertiajs/vue3';
import {art,modes,date} from '../art';
import Avatar from '../Components/Avatar.vue';
import WeekStamps from '../Components/WeekStamps.vue';
defineProps({catalog:Object,stats:Object,assignments:Array,daily:Object,deck:Object,leaders:Object});
const page=usePage();
const menu=[['Maki Mentor','Check answers and read feedback.','maki','/practice?mode=tutor'],['Wasabi Rush','Practice under a timer.','wasabi','/practice?mode=exam'],['Bento Builder','Create exam papers and keys.','chef','/exams'],['Roll Call','Find explanations and bookmarks.','nori','/library']];
</script>
<template><Head title="The Counter"/><div class="counter-heading"><div><p class="eyebrow">Welcome to the counter, {{page.props.community.profile.display_name}}</p><h1>A fresh catch. A stronger memory.</h1></div><Link class="button" href="/passport">Sushi Passport · {{page.props.community.badge_count}} earned</Link></div>
<div class="daily-grid">
<section class="daily-card catch-card"><img :src="art.temaki" alt="Captain Catch" class="daily-character"><p class="eyebrow">Your daily ten</p><h2>Fresh Catch 10</h2><p v-if="daily.completed_today">✓ Today's catch is complete. Your stamp is saved!</p><p v-else-if="daily.attempt">{{daily.answered}} / 10 answered. Your catch is waiting where you left it.</p><p v-else>Ten new or previously missed questions from the subjects you choose.</p><p class="muted">{{daily.subjects.join(' · ')}}</p><Link :href="daily.attempt?'/attempts/'+daily.attempt:'/practice?mode=fresh'" class="button primary">{{daily.attempt?'Resume catch':daily.completed_today?'Take another catch':'Start today’s catch'}}</Link><p v-if="!daily.available" class="muted">Fewer than 10 eligible questions remain in these subjects. Broaden your selection or practice with Memory Maki.</p><div v-if="daily.remind" class="daily-reminder" role="status"><strong>🍣 Your Fresh Catch is waiting.</strong><div><button class="plain" @click="router.post('/reminders/dismiss',{action:'snooze'},{preserveScroll:true})">Remind me in 1 hour</button><button class="plain" @click="router.post('/reminders/dismiss',{action:'skip'},{preserveScroll:true})">Dismiss today</button></div></div><Link v-if="daily.completed_today&&!daily.push_enabled" href="/settings" class="reminder-link">Set up a daily reminder →</Link></section>
<section class="daily-card memory-card"><img :src="art.memo" alt="Memo Maki" class="daily-character"><p class="eyebrow">Keep it rolling</p><h2>Memory Maki</h2><template v-if="deck"><p>{{deck.title}}</p><strong class="coverage-number">{{deck.confident}} / {{deck.total}} confident</strong><div class="meter"><i :style="{width:deck.total?deck.confident/deck.total*100+'%':'0%'}"></i></div><p>{{deck.low}} questions rated 1–2 · {{deck.unrated}} unrated</p><Link :href="'/flashcards/decks/'+deck.id" class="button primary">Resume deck</Link> <Link href="/flashcards">Choose a deck</Link></template><template v-else><p>Choose your questions, answer, then rate how well you know them. The less familiar cards appear more often.</p><Link href="/flashcards" class="button primary">Build your first deck</Link></template><p class="muted">An optional stopping point appears at 80% rated 5.</p></section>
</div>
<WeekStamps :habits="page.props.community.habits"/>
<section v-if="page.props.community.recent_badges.length" class="notice" aria-live="polite"><strong>New in your Passport</strong><p>{{page.props.community.recent_badges.map(b=>b.name).join(' · ')}}</p><Link href="/profile">Explore your unlocked portraits →</Link></section>
<section v-if="assignments.length" class="panel"><h2>Your assigned bentos</h2><div v-for="a in assignments" :key="a.id" class="row"><div><strong>{{a.exam.title}}</strong><p>{{date(a.opens_at)}} to {{date(a.closes_at)}} · {{a.minutes}} minutes</p></div><button @click="router.post('/assignments/'+a.id+'/start')">Start exam</button></div></section>
<section class="panel"><div class="row"><div><p class="eyebrow">This week at the counter</p><h2>Sushi Counter Leaderboard</h2></div><Link class="button" href="/leaderboard">View everyone</Link></div><p v-if="!leaders.rows.length">The first study round starts the story.</p><div v-for="r in leaders.rows.slice(0,3)" :key="r.profile.id" class="leader-row"><strong>#{{r.rank}}</strong><Avatar :avatar="r.profile.avatar" size="small"/><Link :href="'/profiles/'+r.profile.id">{{r.profile.display_name}}</Link><strong>{{r.points}} points</strong></div><p v-if="leaders.my_rank">Your rank this week: #{{leaders.my_rank}}</p></section>
<h2>More at the counter</h2><div class="menu-grid secondary-tools"><Link v-for="[name,description,image,url] in menu" :key="name" :href="url" class="menu-card"><img :src="art[image]" :alt="name"><div><h2>{{name}}</h2><p>{{description}}</p></div></Link></div>
<section v-if="stats.attempts.some(a=>a.status==='active'&&a.mode!=='fresh')" class="panel"><h2>Your other unfinished rounds</h2><div v-for="a in stats.attempts.filter(a=>a.status==='active'&&a.mode!=='fresh')" :key="a.id" class="row"><span>{{modes[a.mode]}} · {{a.items_count}} questions</span><Link :href="'/attempts/'+a.id" class="button">Resume</Link></div></section>
<div class="stat-grid"><div class="stat"><strong>{{stats.completed}}</strong><span>MCQs completed</span></div><div class="stat"><strong>{{stats.first_total?Math.round(stats.first_correct/stats.first_total*100)+'%':'None yet'}}</strong><span>First-attempt accuracy · n={{stats.first_total}}</span></div><div class="stat"><strong>{{catalog.total}}</strong><span>Available questions</span></div></div>
<p class="muted"><Link href="/import">Import offline progress</Link> · <Link href="/password">Change password</Link></p></template>
